export function OrganisationPicker({
  org = "{{org}}",
  memberCount = {{memberCount}},
  verified = {{verified}},
  color = "{{color}}",
  style: pickerStyle = "{{style}}",
}) {
  return (
    <details style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", maxWidth: 280 }}>
      <summary style={{ display: "flex", alignItems: "center", gap: 10, padding: pickerStyle === "compact" ? "6px 10px" : "10px 12px", border: `1.5px solid ${color}`, borderRadius: 10, cursor: "pointer", listStyle: "none", background: "#FAF7F2" }}>
        <span aria-hidden="true" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 32, height: 32, borderRadius: 8, background: color, fontWeight: 700, fontSize: 13, flex: "none" }}>{org.slice(0, 2)}</span>
        <span>
          <strong style={{ display: "block" }}>{org}</strong>
          <span style={{ display: "block", fontSize: 12, opacity: 0.75 }}>{memberCount} members{verified ? " · Verified" : ""}</span>
        </span>
      </summary>
      <ul style={{ margin: "6px 0 0", padding: 6, border: "1px solid #24143022", borderRadius: 10, listStyle: "none", display: "grid", gap: 4 }}>
        <li><button type="button" style={{ width: "100%", textAlign: "left", background: "none", border: "none", padding: "6px 8px", borderRadius: 6, cursor: "pointer", color: "#241430" }}>Northbank Studio</button></li>
        <li><button type="button" style={{ width: "100%", textAlign: "left", background: "none", border: "none", padding: "6px 8px", borderRadius: 6, cursor: "pointer", color: "#241430" }}>Harlow &amp; Vale</button></li>
      </ul>
    </details>
  );
}
